import { computed, effect, signal } from "alien-signals";

const quantity = signal(3);
const price = signal(19);
const discount = signal(2);
const subtotal = computed(() => (quantity() * price()) | 0);
const total = computed(() => (subtotal() - discount()) | 0);

function unusedForecast(months) {
  return ((months * 8_191) | 0) + 17;
}

let digest = 0;
effect(() => {
  digest = ((digest * 33 | 0) + total()) | 0;
});

for (let index = 0; index < 150_000; index += 1) {
  quantity((index % 23) + 1);
  price((index % 41) + 3);
  if (index % 4 === 0) discount(index % 11);
}

console.log(`reactive:${digest}:${total()}`);

class IntSignal {
  constructor(value) {
    this.value = value;
    this.observers = [];
  }

  read() {
    return this.value;
  }

  watch(observer) {
    this.observers.push(observer);
  }

  write(next) {
    if (next === this.value) return;
    this.value = next;
    for (let index = 0; index < this.observers.length; index += 1) {
      this.observers[index](next);
    }
  }
}

let digest = 0;
const quantity = new IntSignal(3);
const price = new IntSignal(19);
const discount = new IntSignal(2);

function updateTotal() {
  const total = (quantity.read() * price.read() | 0) - discount.read();
  digest = ((digest * 33 | 0) + total) | 0;
  return digest;
}

function unusedForecast(months) {
  return (months * 8_191 | 0) + 17;
}

quantity.watch(updateTotal);
price.watch(updateTotal);
discount.watch(updateTotal);
updateTotal();
for (let index = 0; index < 150_000; index += 1) {
  quantity.write((index % 23) + 1);
  price.write((index % 41) + 3);
  if (index % 4 === 0) discount.write(index % 11);
}
console.log(`reactive:${digest}:${(quantity.read() * price.read() | 0) - discount.read()}`);

int digest = 0;

class IntSignal {
  int value;
  (func(int)->int)[] observers;

  init(int value) {
    this.value = value;
  }

  pure int read() {
    return this.value;
  }

  void watch(func(int)->int observer) {
    this.observers.push(observer);
  }

  void write(int next) {
    if (next == this.value) {
      return;
    }
    this.value = next;
    for (int index = 0; index < this.observers.length; index++) {
      func(int)->int observer = this.observers[index];
      observer(next);
    }
  }
}

IntSignal quantity = new IntSignal(3);
IntSignal price = new IntSignal(19);
IntSignal discount = new IntSignal(2);

int updateTotal(int ignored) {
  int subtotal = quantity.read() * price.read();
  int total = subtotal - discount.read();
  digest = digest * 33 + total;
  return digest;
}

pure int unusedForecast(int months) {
  return months * 8191 + 17;
}

quantity.watch(updateTotal);
price.watch(updateTotal);
discount.watch(updateTotal);
updateTotal(0);

for (int index = 0; index < 150000; index++) {
  quantity.write(index % 23 + 1);
  price.write(index % 41 + 3);
  if (index % 4 == 0) {
    discount.write(index % 11);
  }
}

int finalTotal = quantity.read() * price.read() - discount.read();
print(`reactive:${digest}:${finalTotal}`);

import mitt from "mitt";

const events = mitt();
let score = 0;
let observed = 0;

function record(value) {
  score = ((score * 31 | 0) + value) | 0;
}

events.on("metric", record);
events.on("*", (type, value) => {
  observed = (observed + value + type.length) | 0;
});

for (let index = 0; index < 180_000; index += 1) {
  events.emit("metric", index % 97);
}

console.log(`events:${score}:${observed}`);

class MetricEvents {
  constructor() {
    this.metricHandlers = [];
    this.anyHandlers = [];
  }

  onMetric(handler) {
    this.metricHandlers.push(handler);
  }

  onAny(handler) {
    this.anyHandlers.push(handler);
  }

  emitMetric(value) {
    for (let index = 0; index < this.metricHandlers.length; index += 1) {
      this.metricHandlers[index](value);
    }
    for (let index = 0; index < this.anyHandlers.length; index += 1) {
      this.anyHandlers[index](value);
    }
  }
}

let score = 0;
let observed = 0;
function record(value) {
  score = ((score * 31 | 0) + value) | 0;
  return score;
}
function recordAny(value) {
  observed = (observed + value + 6) | 0;
  return observed;
}

const events = new MetricEvents();
events.onMetric(record);
events.onAny(recordAny);
for (let index = 0; index < 180_000; index += 1) events.emitMetric(index % 97);
console.log(`events:${score}:${observed}`);

int score = 0;
int observed = 0;

class MetricEvents {
  (func(int)->int)[] metricHandlers;
  (func(int)->int)[] anyHandlers;

  void onMetric(func(int)->int handler) {
    this.metricHandlers.push(handler);
  }

  void onAny(func(int)->int handler) {
    this.anyHandlers.push(handler);
  }

  void emitMetric(int value) {
    for (int index = 0; index < this.metricHandlers.length; index++) {
      func(int)->int handler = this.metricHandlers[index];
      handler(value);
    }
    for (int index = 0; index < this.anyHandlers.length; index++) {
      func(int)->int handler = this.anyHandlers[index];
      handler(value);
    }
  }
}

int record(int value) {
  score = score * 31 + value;
  return score;
}

int recordAny(int value) {
  observed = observed + value + 6;
  return observed;
}

MetricEvents events = new MetricEvents();
events.onMetric(record);
events.onAny(recordAny);
for (int index = 0; index < 180000; index++) {
  events.emitMetric(index % 97);
}
print(`events:${score}:${observed}`);

function decodeFrame(seed, sharedBytes) {
  const buffer = new ArrayBuffer(96);
  const bytes = new Uint8Array(buffer);
  for (let index = 0; index < bytes.length; index += 1) {
    bytes[index] =
      ((((seed + (index * 17 | 0)) | 0) + (index % 7)) | 0) % 256;
  }

  const payload = bytes.subarray(4, 92);
  let checksum = 0;
  let peaks = 0;
  for (let index = 0; index < payload.length; index += 1) {
    const value = payload[index];
    checksum =
      ((checksum + (value * ((index + 3) | 0) | 0)) | 0) % 1_000_000_007;
    if (value > 239) peaks += 1;
  }
  sharedBytes[seed % sharedBytes.length] = checksum % 256;
  return ((checksum + (peaks * 257 | 0)) | 0) % 1_000_000_007;
}

const shared = new SharedArrayBuffer(32);
const sharedBytes = new Uint8Array(shared);
let digest = 0;
for (let round = 0; round < 20_000; round += 1) {
  digest = ((digest + decodeFrame(round % 251, sharedBytes)) | 0) % 1_000_000_007;
}
for (let index = 0; index < sharedBytes.length; index += 1) {
  digest =
    ((digest + (sharedBytes[index] * ((index + 1) | 0) | 0)) | 0) %
    1_000_000_007;
}
console.log(`binary:${digest}:${shared.byteLength}`);

